"""Generate the command reference from the real CLI parser."""

from __future__ import annotations

import argparse
import os
import sys
from collections.abc import Iterator, Sequence
from contextlib import contextmanager
from pathlib import Path
from typing import cast

from vouch_mk2.cli import _parser


ROOT = Path(__file__).resolve().parents[1]
COMMANDS_PATH = ROOT / "docs" / "commands.md"
HEADER = (
    "<!-- Generated by scripts/gen_commands_doc.py — do not edit; regenerate with "
    "`uv run python scripts/gen_commands_doc.py` -->"
)


@contextmanager
def _fixed_help_width() -> Iterator[None]:
    previous = os.environ.get("COLUMNS")
    os.environ["COLUMNS"] = "100"
    try:
        yield
    finally:
        if previous is None:
            os.environ.pop("COLUMNS", None)
        else:
            os.environ["COLUMNS"] = previous


def _command_parsers() -> list[tuple[str, argparse.ArgumentParser]]:
    with _fixed_help_width():
        parser = _parser()
        action = next(
            action
            for action in parser._actions
            if isinstance(action, argparse._SubParsersAction)
        )
        choices = cast(dict[str, argparse.ArgumentParser], action.choices)
        return list(choices.items())


def render_commands_doc() -> str:
    """Render every subcommand's stable ``--help`` output in parser order."""
    sections = [HEADER, "", "# Command reference"]
    with _fixed_help_width():
        for verb, subparser in _command_parsers():
            subparser.prog = f"vouch-mk2 {verb}"
            help_text = subparser.format_help().rstrip()
            sections.extend(("", f"## {verb}", "", "```text", help_text, "```"))
    return "\n".join(sections) + "\n"


def _difference_summary(actual: str, expected: str) -> str:
    actual_lines = actual.splitlines()
    expected_lines = expected.splitlines()
    for line_number, (actual_line, expected_line) in enumerate(
        zip(actual_lines, expected_lines, strict=False), start=1
    ):
        if actual_line != expected_line:
            return f"line {line_number} differs"
    if len(actual_lines) != len(expected_lines):
        return (
            f"line count differs (found {len(actual_lines)}, "
            f"expected {len(expected_lines)})"
        )
    return "line endings or final newline differ"


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check",
        action="store_true",
        help="exit nonzero when docs/commands.md is not freshly generated",
    )
    arguments = parser.parse_args(argv)
    rendered = render_commands_doc()
    if arguments.check:
        if not COMMANDS_PATH.is_file():
            print(f"{COMMANDS_PATH}: missing generated command reference", file=sys.stderr)
            return 1
        actual = COMMANDS_PATH.read_text(encoding="utf-8")
        if actual != rendered:
            print(
                f"{COMMANDS_PATH}: {_difference_summary(actual, rendered)}",
                file=sys.stderr,
            )
            return 1
        return 0
    COMMANDS_PATH.write_text(rendered, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
